- PED::_ADD_SCENARIO_TRANSITION(ped);
- if (TASK::_TRANSITION_SCENARIO_TO_CONDITIONAL_ANIM(ped, scenarioPoint, clipsetDict, clipName, fromConditionalAnim, 0)) {
    if (PED::IS_PED_USING_THIS_SCENARIO(ped, scenarioPoint)) {
